{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Trazodone, a chloroaryl piperazine antidepressant, has human oral bioavailability of 63–91%, supporting high F for the chloroaromatic heterocyclic-amine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Linezolid, a morpholine-containing amide, is approximately 100% orally bioavailable in humans, directly supporting high F for the morpholine-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Bepotastine, a chlorophenyl-containing drug, has oral bioavailability greater than 80% in humans, supporting high F for the chlorophenyl query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Tazemetostat, a morpholine-containing drug, had median absolute bioavailability of 31.8% with a range of 20.2–49.8%, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Sematilide, a benzamide with a basic amine side chain, had absolute bioavailability of about 46%, structurally close to the query and supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is moclobemide (4-chloro-N-(2-morpholinoethyl)benzamide). All transferable experimental evidence from structurally related chloroaryl and heterocyclic-amine drugs shows oral bioavailability well above 20%, with most analogues in the 44–100% range. Even the lowest relevant absolute bioavailability value (tazemetostat ~32%) exceeds the threshold. A modified-release formulation may alter absorption kinetics but is unlikely to reduce F below 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the query under modified-release conditions.",
    "Modified-release formulation-specific bioavailability data are absent, so the effect of the formulation on F is inferred from conventional oral data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

